declarations.raw_source:
struct CostV1 {
    work: u64,
    storage: u64,
}

enum OwnedFixtureOutcomeV1 {
        SetupRefused(SetupOutcomeV1),
        Loaded {
            original_files: ReturnedLoaderFilesV1,
            original_loader_usage: LoaderUsageV1,
            rows: File,
            snapshot: File,
            cancellation_owner: Cancellation,
            claims_owner: UnverifiedProfileDigestBytesV1,
            primary: PrimaryOutcomeV1,
        },
    }

struct PrepaidOwnedV1<'a, T> {
    owned: Option<T>,
    reservation: Option<ReservationV1<'a>>,
}

enum PrimaryOutcomeV1 {
        LoaderRefused(LoaderFailureV1),
        Leaf(Result<SnapshotScopeFinishV1, SnapshotPreScopeFailureV1>),
    }

struct ReservationV1<'a> {
    account: &'a TrustedHostAccountV1,
    storage: u64,
}

struct ReturnedLoaderFilesV1 {
    pub(super) source: File,
    pub(super) build: File,
    pub(super) session: File,
    pub(super) executable: Option<File>,
}

struct ReviewedWholeQuoteV1 {
    total: CostV1,
}

enum SetupOutcomeV1 {
        Ready { source: File, build: File, session: File, rows: File, snapshot: File },
        Refused { stage: usize, original: io::Error, files: [Option<File>; 5] },
        InvariantRefused { files: [Option<File>; 5] },
    }

enum SnapshotAdmissionErrorV1 {
    Stop(SnapshotStopV1),Owner,Layout,Arithmetic,WorkAuditPending,
    Work {used:u64,requested:u64,limit:u64},
    Storage {current:usize,additional:usize,limit:usize},
}

struct SnapshotPreScopeFailureV1 {
    pub(super) primary:SwiftRunFailure,
    pub(super) retirement:Result<(),SwiftRunFailure>,
}

struct SnapshotPrimaryRetirementV1 {
    variant:u32,primary:Option<SwiftRunFailure>,header_error:Option<ProfileHeaderErrorV1>,
    header:Option<UnverifiedProfileHeaderV1>,rows:Option<Result<ProfileRowsObservationV1,ProfileAdapterErrorV1>>,
    construction_completion:Option<Result<(),SwiftRunFailure>>,adopted_retirement:Result<(),SwiftRunFailure>,
    export:SnapshotAttemptV1,phase_completion:Result<(),SwiftRunFailure>,
}

struct SnapshotWasiAttachmentV1 {
    pub(super) construction:Result<(),SwiftRunFailure>,
    pub(super) completion:Result<(),SwiftRunFailure>,
}

enum SwiftDeadlineOrigin {
    Run,
    Wasi,
}

struct SwiftReservationUsage {
    pub current: usize,
    pub peak: usize,
}

struct SwiftRunUsage {
    pub reservations: SwiftReservations,
    pub live: SwiftLiveUsage,
    pub cache_work: u64,
    pub execution_work: u64,
    pub instruction_fuel: u64,
    pub instructions: u64,
    pub host_calls: u64,
    /// Independent cleanup observation; never replaces the first terminal cause.
    pub cleanup_invariant: Option<SwiftCleanupInvariant>,
    pub elapsed_micros: u64,
    pub deadline_ms: u64,
    pub deadline_origin: SwiftDeadlineOrigin,
    pub deadline_overshoot_micros: u64,
    /// Historical validation observations, never added to runtime admission.
    pub validation: SwiftValidationUsage,
    /// Copied observation only. None means no context observation was supplied;
    /// no field in this snapshot is consulted for admission by RuntimeControl.
    pub wasi: Option<WasiUsage>,
}

struct SwiftValidationFailure {
    pub kind: SwiftValidationFailureKind,
    pub code: &'static str,
    /// Absolute function index, including the 34 imports, when in a body.
    pub function: Option<u32>,
    /// Absolute source byte offset.
    pub offset: usize,
    pub resource: Option<SwiftValidationResource>,
    pub attempted: u64,
    pub limit: u64,
    pub usage: SwiftValidationUsage,
}

struct TrustedHostAccountV1 {
    limits: CostV1,
    usage: Cell<UsageV1>,
    // Retain the independently provisioned P0 authority/allocation record.
    root: TrustedRootPolicyV1,
}

struct TrustedRootPolicyV1 {
    child_limits: CostV1,
    p0_preexisting_allocation: CostV1,
    source_and_review_binding: [u8; 32],
}

struct UnverifiedProfileDigestBytesV1 {
    baseline:[u8;32], candidate:[u8;32], original_input:[u8;32], event_schema:[u8;32],
    profile_adapter_binary:[u8;32], layout_receipt:[u8;32], original_validated_snapshot:[u8;32], profile_row_body:[u8;32],
}

struct UsageV1 {
    work: u64,
    storage: u64,
    peak_storage: u64,
}

struct WasiUsage {
    pub calls: u64,
    pub work: u64,
    pub transfer_bytes: u64,
    /// Successful OS random bytes, including bytes discarded after a later failure.
    pub random_bytes: u64,
    pub log_bytes: u64,
    /// Non-success errno outcomes and the first terminal failure/exit.
    pub failures: u64,
    pub reservations: WasiReservations,
}

struct SelectedValidatedProfileV1 {
    proof: ValidatedSwiftReactor,
    provenance: LoaderProvenanceV1,
}

struct AdoptionBodyV1 {
    proof: ValidatedSwiftReactor,
    selected: Option<LoaderProvenanceV1>,
}

struct Buffer<T: Copy> {
    values: Vec<T>,
    charged: usize,
    category: Resource,
}

struct SwiftDeclaration {
    pub memory_maximum: Option<u32>,
    pub table_maximum: Option<u32>,
    pub memory_offset: usize,
    pub table_offset: usize,
}

struct Signature {
    pub first: u32,
    pub count: u32,
    pub result: Option<Type>,
}

struct Import {
    pub(super) module: Span,
    pub(super) name: Span,
    pub type_index: u32,
}

struct Function {
    pub body: Span,
    pub type_index: u32,
}

struct Global {
    pub ty: Type,
    pub mutable: bool,
    pub initializer: Span,
}

struct Export {
    pub(super) name: Span,
    pub(super) kind: u8,
    pub(super) index: u32,
}

struct Segment {
    pub payload: Span,
    pub destination: u32,
    pub count: u32,
}

struct Span {
    pub offset: u32,
    pub bytes: u32,
}

enum Type {
    I32,
    I64,
    F32,
    F64,
}

enum Policy<'a> {
    Frozen(&'a Limits),
    #[cfg(feature = "experimental-swift-reactor")]
    SwiftReactorExperimentV1,
}

enum Resource {
    Source,
    Metadata,
    Scratch,
    Work,
    /// An unchanged executable-profile count/stack/table/memory ceiling.
    Profile,
}

struct AdoptedProof {
    body: AdoptionBodyV1,
    source: ReservationTicket,
    metadata: ReservationTicket,
}

struct ReservationTicket {
    owner: u64,
    category: SwiftReservationCategory,
    bytes: usize,
}

struct SwiftSlot {
    resident: Option<SwiftResident>,
    pins: usize,
    last_used: u64,
}

struct SwiftResident {
    decoded: DecodedFunction,
    ticket: ReservationTicket,
}

struct ScanPlan {
    function: u32,
    body_offset: usize,
    body_len: usize,
    type_index: u32,
    counts: decode::Counts,
}

struct CacheConstructionFailure {
    pub failure: SwiftRunFailure,
    pub rejected_adopted: Option<AdoptedProof>,
}

struct PinRecord {
    pub(crate) nonce: u64,
    pub(crate) entry: usize,
}

struct DecodedInstruction {
    pub operation: Operation,
    pub offset: usize,
}

enum Operation {
    Unreachable,
    Nop,
    Block {
        kind: ControlKind,
        result: Option<Type>,
        end: usize,
        alternative: Option<usize>,
    },
    Else {
        end: usize,
    },
    End,
    Br(u32),
    BrIf(u32),
    BrTable {
        first: usize,
        count: usize,
        default: u32,
    },
    Return,
    Call(u32),
    CallIndirect(u32),
    MemoryCopy,
    MemoryFill,
    Drop,
    Select,
    LocalGet(u32),
    LocalSet(u32),
    LocalTee(u32),
    GlobalGet(u32),
    GlobalSet(u32),
    Load {
        opcode: u8,
        offset: u32,
    },
    Store {
        opcode: u8,
        offset: u32,
    },
    MemorySize,
    MemoryGrow,
    Const(Value),
    Numeric(u8),
    Saturating(u8),
}

enum ControlKind {
    Block,
    Loop,
    If,
}

enum Value {
    I32(i32),
    I64(i64),
    /// Raw IEEE-754 bits preserve signed zero and NaN payloads.
    F32(u32),
    F64(u64),
}

struct Patch {
    start: usize,
    alternative: Option<usize>,
    kind: ControlKind,
}

struct Counts {
    locals: usize,
    instructions: usize,
    targets: usize,
}

struct Span {
    start: usize,
    end: usize,
}

enum WasiOutcome {
    Errno(Errno),
    Exit(u32),
    Failure(WasiFailure),
}

struct SnapshotOuterV1 {
    primary:InitialProfileConstructionOutcomeV1,export:SnapshotAttemptV1,phase_completion:Result<(),SwiftRunFailure>,
}
